#!/usr/bin/env node
// Copies deployments/*.json and the ABIs the front needs from the Foundry
// artifacts (../out) into lib/monad/generated/*.ts, as typed `as const` modules.
//
// Runs before `dev` and `build`. If ../out or ../deployments is missing
// (fresh clone, CI, Vercel), the previously generated files are kept so the
// build still works: lib/monad/generated is meant to be committed.

import {existsSync, mkdirSync, readFileSync, readdirSync, writeFileSync} from "node:fs";
import {dirname, join} from "node:path";
import {fileURLToPath} from "node:url";

const here = dirname(fileURLToPath(import.meta.url));
const appRoot = join(here, "..");
const repoRoot = join(appRoot, "..");
const outDir = join(repoRoot, "out");
const deploymentsDir = join(repoRoot, "deployments");
const genDir = join(appRoot, "lib", "monad", "generated");

mkdirSync(genDir, {recursive: true});

const HEADER = "// AUTO-GENERATED by scripts/sync-monad.mjs. Do not edit by hand.\n";

// [exportName, artifact file, contract name]
const ABIS = [
  ["earnRouterAbi", "AgamaEarnRouter.sol", "AgamaEarnRouter"],
  ["amplifyRouterAbi", "AgamaAmplifyRouter.sol", "AgamaAmplifyRouter"],
  ["accountAbi", "AgamaAccount.sol", "AgamaAccount"],
  ["accountFactoryAbi", "AgamaAccountFactory.sol", "AgamaAccountFactory"],
  ["lendingPoolAbi", "ArrowLendingPool.sol", "ArrowLendingPool"],
  ["stabilityPoolAbi", "ArrowStabilityPool.sol", "ArrowStabilityPool"],
  ["xStockAdapterAbi", "ArrowXStockAdapter.sol", "ArrowXStockAdapter"],
  ["vaultShareAdapterAbi", "ArrowVaultShareAdapter.sol", "ArrowVaultShareAdapter"],
  ["stockOracleAbi", "DataStreamsStockOracle.sol", "DataStreamsStockOracle"],
  ["sagUsdAbi", "sagUSD.sol", "sagUSD"],
  ["agUsdQueueAbi", "agUSDQueue.sol", "agUSDQueue"],
  ["debtTokenAbi", "DebtToken.sol", "DebtToken"],
  ["zapRouterAbi", "AgamaZapRouter.sol", "AgamaZapRouter"],
];

// ---- ABIs ---------------------------------------------------------------------

if (existsSync(outDir)) {
  const errors = new Map();
  let src = HEADER;
  let ok = true;
  for (const [name, file, contract] of ABIS) {
    const p = join(outDir, file, `${contract}.json`);
    if (!existsSync(p)) {
      console.warn(`[sync] missing artifact ${p}, keeping the previous abis.ts`);
      ok = false;
      break;
    }
    const abi = JSON.parse(readFileSync(p, "utf8")).abi;
    for (const item of abi) {
      if (item.type !== "error") continue;
      const sig = `${item.name}(${item.inputs.map((i) => i.type).join(",")})`;
      if (!errors.has(sig)) errors.set(sig, item);
    }
    src += `\nexport const ${name} = ${JSON.stringify(abi, null, 2)} as const;\n`;
  }
  if (ok) {
    // Every custom error of the stack, used to decode reverts that bubble up
    // from nested calls (pool, adapters, oracle, vault) through the routers.
    src += `\nexport const allErrorsAbi = ${JSON.stringify([...errors.values()], null, 2)} as const;\n`;
    writeFileSync(join(genDir, "abis.ts"), src);
    console.log(`[sync] abis.ts: ${ABIS.length} contracts, ${errors.size} errors`);
  }
} else if (existsSync(join(genDir, "abis.ts"))) {
  console.log("[sync] ../out not found, keeping the committed abis.ts");
} else {
  console.error("[sync] ../out not found and no committed abis.ts. Run `forge build` in the repo root.");
  process.exit(1);
}

// ---- Deployments -----------------------------------------------------------------

if (existsSync(deploymentsDir)) {
  // `<id>.json` wins. `<id>-fork.json` (a local fork deploy of that chain) is
  // opt-in through INCLUDE_FORK_DEPLOYMENTS=1, so a production build never
  // shows fork addresses to a wallet connected to the real chain.
  const withForks = process.env.INCLUDE_FORK_DEPLOYMENTS === "1";
  const all = {};
  const sources = {};
  for (const f of readdirSync(deploymentsDir).sort()) {
    const m = /^(\d+)(-fork)?\.json$/.exec(f);
    if (!m) continue;
    if (m[2] && !withForks) continue;
    const id = m[1];
    // 1961 is the local anvil fork of Monad. It only exists on a developer's
    // machine, so it never belongs in a committed or deployed bundle.
    if (id === "1961" && !withForks) continue;
    if (m[2] && sources[id] && !sources[id].endsWith("-fork.json")) continue;
    if (!m[2] || !all[id]) {
      all[id] = JSON.parse(readFileSync(join(deploymentsDir, f), "utf8"));
      sources[id] = f;
    }
  }
  const src =
    HEADER +
    `import type {Deployment} from "../deployment-types";\n\n` +
    `export const deployments: Partial<Record<number, Deployment>> = ${JSON.stringify(all, null, 2)};\n\n` +
    `/// Which file each deployment came from ("196-fork.json" = local fork deploy).\n` +
    `export const deploymentSources: Partial<Record<number, string>> = ${JSON.stringify(sources, null, 2)};\n`;
  writeFileSync(join(genDir, "deployments.ts"), src);
  console.log(`[sync] deployments.ts: ${Object.entries(sources).map(([k, v]) => `${k} (${v})`).join(", ") || "(none)"}`);
} else if (existsSync(join(genDir, "deployments.ts"))) {
  console.log("[sync] ../deployments not found, keeping the committed deployments.ts");
} else {
  writeFileSync(
    join(genDir, "deployments.ts"),
    HEADER +
      `import type {Deployment} from "../deployment-types";\n\nexport const deployments: Partial<Record<number, Deployment>> = {};\n` +
      `export const deploymentSources: Partial<Record<number, string>> = {};\n`,
  );
  console.log("[sync] no deployments found, wrote an empty deployments.ts");
}
